import os
import urllib
import mimetypes
import logging

log = logging.getLogger(__name__)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            mime = mimetypes.MimeTypes()
            self.type = mime.guess_type(urllib.pathname2url(self.path))[0]


    def get_type(self):
        if not self._type:
            url = urllib.pathname2url(self.path)
            guess = self.mime.guess_type(url)[0]

            if not guess or guess == 'application/octet-stream':
                # some files have no mime-type or only a generic one, try to get it from the extension
                ext = os.path.splitext(self.name)[1].replace('.', '')

                if ext.upper() in FILETYPE_EXTENSIONS:
                    guess = FILETYPE_EXTENSIONS[ext.upper()]
            self._type = guess
        return self._type

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

