import unittest

import numpy as np

from chainer import cuda
from chainer import function
from chainer import tests


class CopyTest(unittest.TestCase):

    def setUp(self):
        self.copy = function.Copy(cuda.Device(0))
        if cuda.cupy is not None:
            self.x_gpu = cuda.cupy.arange(3).astype(np.float32)
        else:
            self.x_gpu = cuda.cupy.arange(3).astype(np.float32)
        self.x_cpu = chainer.get_device(self.x_gpu).data
        self.y = self.copy(self.x_gpu)

    def check_forward(self, x_data):
        y = self.copy(x_data)
        self.assertEqual(y.data.device, cuda.Device(0))
        np.testing.assert_array_equal(y.data, x_data)

    def test_forward_cpu(self):
        self.check_forward(self.x_cpu)

    def test_forward_gpu(self):
        self.check_forward(self.x_gpu)

    def check_backward(self, x_data):
        x = chainer.Variable(x_data)
        y = self.copy(x)
        y_sum = chainer.functions.sum(y)
        y_sum.backward()
        self.assertTrue(x.grad is not None)
        np.testing.assert_array_equal(x.grad.data, 1)

    def test_backward_cpu(self):
        self.check_backward(self.x_cpu)

    def test_backward_gpu(self):
        self.check_backward(self.x_gpu)


def main():
    unittest.main()


if __name__ == '__main__':
    main()

import unittest

from chainer import cuda
from chainer import function
from chainer import testing
from chainer.utils import type_check


class CopyTest(unittest.TestCase):

    def test_data_check(self):
        x = type_check.Variable(None, 'x')
        y = type_check.Variable(None, 'y')
        CheckData(x, y)(x, y)


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_types):
        type_check.expect(in_types.size() == 1)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


class CheckData(function.Function):

    """Check the type of copy function."""

    def check_type_forward(self, in_types):
        type_check.expect(in_types.size() == 2)
        param = in_types[1].type()
        assumed = type_check.Variable(
            cuda.cupy.ndarray((1, 2, 3)), 'x').type()
        assumed_data = type_check.Variable(
            cuda.cupy.ndarray((1, 2, 3)),
            out_device=0).type()
        msg = ''
        if param.dtype != assumed.dtype:
            msg = 'dtype mismatch. Expected: %s' % assumed.dtype
        if param.ndim != assumed.ndim:
            msg = 'ndim mismatch. Expected: %s' % assumed.ndim
        if tuple(param.shape) != assumed.shape:
            msg = 'shape mismatch. Expected: %s' % assumed.shape
        if msg != '':
            raise type_check.TypeError(msg)

    def check_type_backward(self, in_types, out_types):
        out_param = out_types[0].type()
        in_param = in_types[0].type()
        assumed_data = type_check.Variable(
            cuda.cupy.ndarray((1, 2, 3)),
            out_device=0).type()
        assumed = type_check.Variable(
            cuda.cupy.ndarray((1, 2, 3)), 'x').type()
        msg = ''
        if out_param.dtype != in_param.dtype:
            msg = 'dtype mismatch. Expected: %s' % in_param.dtype
        if out_param.ndim != in_param.ndim:
            msg = 'ndim mismatch. Expected: %s' % in_param.ndim
        if tuple(out_param.shape) != in_param.shape:
            msg = 'shape mismatch. Expected: %s' % in_param.shape
        if out_param != assumed_data:
            msg = 'device mismatch. Expected: %s' % assumed_data[out_param]
        if msg != '':
            raise type_check.TypeError(msg)


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


