from os import walk, sep, chdir, pardir, split, join, abspath
from glob import glob
from re import compile, VERBOSE, UNICODE

# System path separator (usually slash or backslash)
sepd = {"sep": sep}

# Files having at least one of these in their path will be excluded
EXCLUDE = set([
    "%(sep)sthirdparty%(sep)s" % sepd,
    "%(sep)sprinting%(sep)spretty%(sep)s" % sepd,
])

# These tokens are allowed to contain trailing whitespace
ALLOWED = compile(r"""
    ("|"|<<|>>|!=|==|>=|<=|<|>|%|/|//)    # operators
    | \*{2,7}                           # doctest flags
    |(doctest\.contains)             # method name
    | (\'\'\'[^\n]+\n.{60,}.+\'\'\')      # docstring
    """% sepd, VERBOSE|UNICODE)

def is_comment(line):
    return line.lstrip().startswith("#")

def has_trailing_whitespace(s):
    """ Returns True if s ends with whitespace that is not part of a comment,
    a doctest or docstring, or a long string literal."""
    for s in s.splitlines():
        if is_comment(s):
            continue
        if ALLOWED.search(s) is not None:
            continue
        if s.endswith(" \n"):
            return True
    return False

def test_no_trailing_whitespace():
    message = "File contains trailing whitespace: %s, line %s."
    base_path = split(__file__)[0]
    base_path += sep + pardir + sep + pardir # go to sympy/
    base_path = abspath(base_path)
    for root, dirs, files in walk(base_path):
        for fname in glob(join(root, "*.py")):
            if filter(lambda ex: ex in fname, EXCLUDE):
                continue
            file = open(fname, "r")
            try:
                for idx, line in enumerate(file):
                    if has_trailing_whitespace(line):
                        assert False, message % (fname, idx+1)
            finally:
                file.close()

def test_whitespace_in_repr_tests():
    from sympy.printing.pretty.tests.test_repr import repr_test
    for element in repr_test:
        assert not has_trailing_whitespace(element)

