        type_check.expect(in_types.size() == 1)

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)

        in_var = type_check.make_variable(in_types, 'x')
        out_var = type_check.make_variable(out_types, 'y')
        expect = in_var.dtype if in_var.device.major >= 0 else in_var.dtype
        actual = out_var.dtype if out_var.device.major >= 0 else out_var.dtype
        type_check.expect(expect == actual)

    def check_device_forward(self, in_device):
        if in_device.major >= 0:
            self.out_device.to_device(in_device.major)

    def check_device_backward(self, in_device, out_device):
        if in_device.major >= 0:
            in_device.to_device(out_device.major)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


